INSERT INTO `card` VALUES ('c1ce4348e266414c', 1031471, '超级赛亚人4悟吉达', '释放究极之光的战士', 100, '超速', 77, 5, 18813, 9975, 14595, '2025-07-22 16:00:00', '{\"linkId\": [29, 47, 124, 60, 95, 109, 125], \"nextCards\": [{\"nextCard\": {\"id\": 1031471, \"name\": \"超级赛亚人4悟吉达\", \"type\": 0}, \"nextCardId\": 1031471}], \"potential\": [{\"hp\": 2000, \"atk\": 2000, \"def\": 2000}, {\"hp\": 3300, \"atk\": 3700, \"def\": 4100}, {\"hp\": 3600, \"atk\": 4000, \"def\": 4400}, {\"hp\": 3910, \"atk\": 4700, \"def\": 4710}, {\"hp\": 4600, \"atk\": 5000, \"def\": 5400}], \"categoryId\": [1, 2, 39, 46, 60, 72, 75, 80, 83, 84, 85, 95], \"leaderSkill\": \"「GT HERO」类别的\\n气力+4、HP、ATK、DEF提升220%\", \"carnivalFlag\": true, \"freeCardFlag\": false, \"activeSkillId\": 324, \"dokkanFesFlag\": false, \"skillLevelMax\": 20, \"finishSkillIds\": [], \"activeSkillName\": \"龙拳\", \"specialSkillIds\": [7735, 7736], \"standBySkillIds\": [], \"leaderSkillSetId\": 103147, \"passiveSkillDesc\": \"*队伍里除自身以外，\\n有2名以上「GT HERO」类别的角色时，\\n发动登场时动画*\\n‧{passiveImg:once}1回合内追加发动必杀技、必可发动奋力一击\\n‧{passiveImg:once}4回合内我方全体超系的气力+3、DEF70%{passiveImg:up_g}\\n*基本效果*\\n‧气力+3、ATK与DEF300%{passiveImg:up_g}\\n‧取得气珠时气力再+1\\n‧对全属性造成属性克制伤害\\n‧高机率发动奋力一击\\n‧防御所有攻击\\n‧伤害减轻率50%{passiveImg:up_g}\\n‧追加发动必杀技\\n*攻击时*\\n‧ATK300%{passiveImg:up_g}\\n*受到攻击时*\\n‧DEF200%{passiveImg:up_g}\\n*受到敌人的必杀技攻击时*\\n‧暂时使DEF200%{passiveImg:up_g}\\n*受到敌人的气弹系必杀技攻击时*\\n‧超高机率使其无效，并以超绝大威力反击\\n‧若HP为70%以下，\\n必可使其无效，并以超绝大威力反击\\n*战斗中受到3次以上敌人的攻击后*\\n‧{passiveImg:forever}下一个自身的进攻回合起，\\n追加发动必杀技\\n*战斗中受到7次以上敌人的攻击后*\\n‧{passiveImg:forever}气力+4\\n‧{passiveImg:forever}必可发动奋力一击\", \"passiveSkillName\": \"浑然一体的光芒\", \"activeSkillEffect\": \"暂时使ATK超大幅提升\\n并对目标造成究极伤害 & \\n1回合内自身的ATK与DEF提升70%，\\n且必可发动奋力一击\", \"passiveSkillSetId\": 4634, \"activeSkillCondition\": \"受到敌人的攻击后，\\n下一个进攻回合起可发动\\n(仅限1次)\"}', 'system', '2026-01-04 16:46:22', 'system', '2026-01-04 16:46:22');
